  af_cells m3 j0 -> 0 <= b1 < 256 -> b1 mod 4 = 1 ->
  rw_cells asegs m3 (AB + rz_size n + -16) [CB 1 h0; C1 (Z_to_bv 8 b1); C2 (Z_to_bv 64 0); C4 (Z_to_bv 64 n); C8 ctx] ->
